class GamePlatformPage extends StatefulWidget { final String territory; final List<GamePlatformGroup> groups; const GamePlatformPage({super.key,required this.territory,required this.groups}); @override State<GamePlatformPage> createState()=>_GamePlatformPageState(); }
class _GamePlatformPageState extends State<GamePlatformPage> with SingleTickerProviderStateMixin { late final AnimationController clock=AnimationController(vsync:this,duration:const Duration(seconds:100))..repeat(); int? selected; List<GamePlatform> get platforms=>widget.groups.expand((g)=>g.platforms).toList(growable:false); @override void dispose(){clock.dispose();super.dispose();} void enter(int i){final p=platforms[i];Navigator.of(context).push(MaterialPageRoute(builder:(_)=>GameListPage(territory:widget.territory,platform:p.name,externalPlatformIds:p.externalPlatformIds,navigationPlatforms:platforms,navigationIndex:i)));}
@override Widget build(BuildContext context){final size=MediaQuery.sizeOf(context);final compact=size.width<820;return Scaffold(backgroundColor:const Color(0xFF01030A),body:AnimatedBuilder(animation:clock,builder:(_,__)=>Stack(fit:StackFit.expand,children:[CustomPaint(painter:_Space(clock.value)),SafeArea(child:Padding(padding:EdgeInsets.fromLTRB(compact?14:34,compact?12:24,compact?14:34,0),child:Row(children:[IconButton(onPressed:()=>Navigator.pop(context),icon:const Icon(Icons.arrow_back_ios_new,size:14,color:Color(0x99FFFFFF))),const SizedBox(width:8),Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('${widget.territory.toUpperCase()} / PLATFORM WORLDS',style:const TextStyle(fontSize:11,letterSpacing:3.2)),const SizedBox(height:5),const Text('GENERATIONAL ARCHIVE / ORBITAL SYSTEM',style:TextStyle(fontSize:6.5,letterSpacing:2.4,color:Color(0x5AFFFFFF)))]),const Spacer(),Text('${platforms.length.toString().padLeft(2,'0')} WORLDS',style:const TextStyle(fontSize:7,letterSpacing:2,color:Color(0x66FFFFFF)))]))),Center(child:LayoutBuilder(builder:(_,b){final d=(math.min(b.maxWidth*(compact?.98:.84),b.maxHeight*(compact?.72:.80))).toDouble();return SizedBox.square(dimension:d,child:Stack(clipBehavior:Clip.none,children:[Positioned.fill(child:CustomPaint(painter:_Orbits(clock.value,platforms.length))),for(var i=0;i<platforms.length;i++)_Node(platform:platforms[i],index:i,total:platforms.length,selected:selected==i,diameter:d,phase:clock.value,onTap:()=>setState(()=>selected=selected==i?null:i),onOpen:()=>enter(i)),const Positioned.fill(child:IgnorePointer(child:Center(child:_Core())))]));})),Positioned(top:compact?74:92,right:compact?14:36,child:_Telemetry(count:platforms.length,selected:selected)),Positioned(left:compact?12:34,right:compact?12:34,bottom:compact?12:24,child:selected==null?const Center(child:Text('1× CLICK FOCUS    2× CLICK ENTER PLATFORM',style:TextStyle(fontSize:6.5,letterSpacing:1.8,color:Color(0x55FFFFFF)))):_Panel(platform:platforms[selected!],index:selected!,total:platforms.length,onClose:()=>setState(()=>selected=null),onOpen:()=>enter(selected!)))])));}
}
class GamePlatformGroup{final String name;final String subtitle;final List<GamePlatform> platforms;const GamePlatformGroup(this.name,this.subtitle,this.platforms);} class GamePlatform{final String name;final List<int> externalPlatformIds;const GamePlatform(this.name,this.externalPlatformIds);}
class _Telemetry extends StatelessWidget{final int count;final int? selected;const _Telemetry({required this.count,required this.selected});@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.symmetric(horizontal:10,vertical:8),decoration:BoxDecoration(color:const Color(0xB8060A12),border:Border.all(color:const Color(0x2E8EA5B8))),child:Column(crossAxisAlignment:CrossAxisAlignment.end,children:[const Text('ATLAS LINK / ONLINE',style:TextStyle(fontSize:6,letterSpacing:1.6,color:Color(0x709BB0BF))),const SizedBox(height:5),Text('WORLDS ${count.toString().padLeft(2,'0')}',style:const TextStyle(fontSize:6,letterSpacing:1.4,color:Color(0x8AFFFFFF))),Text('FOCUS ${selected==null?'--':(selected!+1).toString().padLeft(2,'0')}',style:const TextStyle(fontSize:6,letterSpacing:1.4,color:Color(0x8AFFFFFF)))]));}
class _Node extends StatelessWidget{final GamePlatform platform;final int index,total;final bool selected;final double diameter,phase;final VoidCallback onTap,onOpen;const _Node({required this.platform,required this.index,required this.total,required this.selected,required this.diameter,required this.phase,required this.onTap,required this.onOpen});@override Widget build(BuildContext c){final center=diameter/2;final orbit=diameter*(.19+(index%5)*.065);final angle=-math.pi/2+index*math.pi*2/math.max(1,total)+phase*math.pi*.22*(index.isEven?1:-1);final p=Offset(center+math.cos(angle)*orbit,center+math.sin(angle)*orbit);final node=(selected?math.max(72,diameter*.112):math.max(52,diameter*.073)).toDouble();return Positioned(left:p.dx-node/2,top:p.dy-node/2,width:node,height:node+28,child:GestureDetector(onTap:onTap,onDoubleTap:onOpen,child:Column(children:[SizedBox.square(dimension:node,child:CustomPaint(painter:_World(seed:index,selected:selected,phase:phase))),const SizedBox(height:4),Text(platform.name,maxLines:1,overflow:TextOverflow.ellipsis,style:TextStyle(fontSize:selected?8:6.2,letterSpacing:1.5,color:Colors.white.withValues(alpha:selected?.96:.5)))])));}}
class _World extends CustomPainter{final int seed;final bool selected;final double phase;const _World({required this.seed,required this.selected,required this.phase});@override void paint(Canvas canvas,Size size){final c=size.center(Offset.zero);final r=size.width*.36;final sphere=Rect.fromCircle(center:c,radius:r);final base=Color([0xFF8B7A6D,0xFF647B87,0xFF8C927E,0xFF7D6F83,0xFF718A86,0xFF9A806B][seed%6]);canvas.drawCircle(c,r,Paint()..shader=RadialGradient(center:Alignment(-.42,-.5),radius:1.05,colors:[base,base.withValues(alpha:.76),const Color(0xFF26313A),const Color(0xFF04060A)]).createShader(sphere));canvas.save();canvas.clipPath(Path()..addOval(sphere));final rnd=math.Random(700+seed*91);for(var i=0;i<28;i++){final p=Offset(c.dx+(rnd.nextDouble()*2-1)*r*.88,c.dy+(rnd.nextDouble()*2-1)*r*.88);canvas.drawCircle(p,.7+rnd.nextDouble()*r*.05,Paint()..color=Colors.white.withValues(alpha:.02+rnd.nextDouble()*.05));}final contour=Paint()..style=PaintingStyle.stroke..strokeWidth=.5..color=const Color(0x329BAFBA);for(var i=-2;i<=2;i++)canvas.drawOval(Rect.fromCenter(center:c.translate(i*r*.19,0),width:r*(.44+(i+2)*.16),height:r*1.82),contour);canvas.restore();canvas.drawCircle(c,r,Paint()..style=PaintingStyle.stroke..strokeWidth:selected?1.25:.65..color=const Color(0x6A9AAEBB));} @override bool shouldRepaint(covariant _World old)=>old.seed!=seed||old.selected!=selected||old.phase!=phase;}
class _Orbits extends CustomPainter{final double phase;final int count;const _Orbits(this.phase,this.count);@override void paint(Canvas c,Size s){final center=s.center(Offset.zero);for(var i=0;i<7;i++){final r=s.shortestSide*(.18+i*.052);c.drawOval(Rect.fromCenter(center:center,width:r*2,height:r*1.15),Paint()..style=PaintingStyle.stroke..strokeWidth:i==6?.9:.45..color=const Color(0x1F90A7B7));}c.drawArc(Rect.fromCenter(center:center,width:s.width*.84,height:s.height*.48),phase*math.pi*2,.65,false,Paint()..style=PaintingStyle.stroke..strokeWidth=1.1..color=const Color(0x507F9AAC));} @override bool shouldRepaint(covariant _Orbits old)=>old.phase!=phase||old.count!=count;}
