class _Panel extends StatelessWidget{final GamePlatform platform;final int index,total;final VoidCallback onClose,onOpen;const _Panel({required this.platform,required this.index,required this.total,required this.onClose,required this.onOpen});@override Widget build(BuildContext c)=>Container(padding:const EdgeInsets.fromLTRB(18,14,12,14),decoration:BoxDecoration(color:const Color(0xF2070B12),border:Border.all(color:const Color(0x527E98A9)),boxShadow:const[BoxShadow(color:Colors.black87,blurRadius:40)]),child:Row(children:[Container(width:3,height:48,color:const Color(0xFF9DB7C7)),const SizedBox(width:13),Expanded(child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('PLATFORM WORLD / ${index+1}/$total',style:const TextStyle(fontSize:6.5,letterSpacing:1.8,color:Color(0x62FFFFFF))),const SizedBox(height:5),Text(platform.name,style:const TextStyle(fontSize:16,letterSpacing:2.8)),const SizedBox(height:4),const Text('GENERATION ARCHIVE • GAME CATALOG • REGION LINKED',style:TextStyle(fontSize:6.2,letterSpacing:1.3,color:Color(0x70FFFFFF)))])),InkWell(onTap:onClose,child:const Padding(padding:EdgeInsets.all(8),child:Text('×',style:TextStyle(fontSize:18,color:Color(0xAAFFFFFF))))),const SizedBox(width:4),FilledButton(onPressed:onOpen,child:const Text('ENTER ARCHIVE'))]));}
class _Space extends CustomPainter{final double phase;const _Space(this.phase);@override void paint(Canvas c,Size s){final rect=Offset.zero&s;c.drawRect(rect,Paint()..shader=const RadialGradient(center:Alignment(0,-.05),radius:1.15,colors:[Color(0xFF0C1420),Color(0xFF030711),Color(0xFF010207)]).createShader(rect));final rnd=math.Random(1188);for(var i=0;i<420;i++){final p=Offset(rnd.nextDouble()*s.width,rnd.nextDouble()*s.height);final a=.025+.11*((math.sin(phase*math.pi*2*(1+i%3)+i)+1)/2);c.drawCircle(p,.25+rnd.nextDouble()*.7,Paint()..color=Colors.white.withValues(alpha:a));}}@override bool shouldRepaint(covariant _Space old)=>old.phase!=phase;}
